refentry.refsect1:
  &reftitle.examples;

   Io\Poll\Watcher::getTriggeredEvents example


<?php
use Io\Poll\Context;
use Io\Poll\Event;
use Time\Duration;

[$reader, $writer] = stream_socket_pair(STREAM_PF_UNIX, STREAM_SOCK_STREAM, STREAM_IPPROTO_IP);

$context = new Context();
$watcher = $context->add(new StreamPollHandle($reader), [Event::Read]);
var_dump($watcher->getTriggeredEvents());

fwrite($writer, 'ping');
fclose($writer);

$context->wait(Duration::fromSeconds(1));
var_dump($watcher->getTriggeredEvents());


   &example.outputs;


array(0) {
}
array(2) {
  [0]=>
  enum(Io\Poll\Event::Read)
  [1]=>
  enum(Io\Poll\Event::HangUp)
